    def test_parse_email_6(self) -> None:
        with pathlib.Path(samples_dir, 'sample_attachments.eml').open('rb') as fhdl:
            raw_email = fhdl.read()

        ep = eml_parser.EmlParser(include_attachment_data=True)
        test = ep.decode_email_bytes(raw_email)

